window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aaa7e3f175f42b61"]={"versions": [{"id": "FIG-aaa7e3f175f42b61", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Mappings von Modellelementen und Instanzreferenzen über verschiedene Sichten hinweg im Rahmen der AUTOSAR Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ViewMapSet</strong> (<code>&lt;&lt;ARElement&gt;&gt;</code>): Eigenständiges Modellpaket bzw. Wurzelelement zur Bündelung von Abbildungsvorschriften; besitzt per Komposition (<code>+viewMap</code>, Multiplizität <code>0..*</code>) untergeordnete Abbildungen.</li>\n<li><strong>ViewMap</strong> (<code>&lt;&lt;Identifiable&gt;&gt;</code>): Repräsentiert ein einzelnes Mapping zwischen Modellelementen bzw. Instanzen. Besitzt das optionale Attribut <code>+ role :Identifier [0..1]</code>. Es verbindet Ziel- und Quellelemente über vier gerichtete Assoziationen:</li>\n<li><code>+firstElement</code>: Unidirektionale Assoziation auf <code>Referrable</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+secondElement</code>: Unidirektionale Assoziation auf <code>Referrable</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+firstElementInstance</code>: Komposition auf <code>AnyInstanceRef</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+secondElementInstance</code>: Komposition auf <code>AnyInstanceRef</code> (Multiplizität <code>0..*</code>).</li>\n<li><strong>Referrable</strong>: Abstraktes Ziel- bzw. Basiselement für referenzierbare Entitäten mit dem Attribut <code>+ shortName :Identifier</code>.</li>\n<li><strong>AnyInstanceRef</strong> (<code>&lt;&lt;AtpInstanceRef&gt;&gt;</code>): Repräsentiert konkrete Instanzreferenzen im Modellkontext, eingebettet in <code>ViewMap</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entitäten definieren deklarative Zuordnungen (Mapping-Definitionen) zwischen Paaren von Elementen (<code>firstElement</code> zu <code>secondElement</code>) bzw. konkreten Instanzreferenzen (<code>firstElementInstance</code> zu <code>secondElementInstance</code>), aggregiert in einem <code>ViewMapSet</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>ViewMapSet</code> dient als transportables <code>ARElement</code> im ARXML-Dateiaustausch.</li>\n<li>Eine <code>ViewMap</code> kann sowohl reine Definitionselemente (<code>Referrable</code>) als auch kontextspezifische Instanzen (<code>AnyInstanceRef</code>) aufeinander abbilden.</li>\n<li>Die Multiplizitäten <code>0..*</code> an allen vier Referenzrollen erlauben n:m-Beziehungen sowie einseitige oder leere Zuordnungen, wobei die semantische Konsistenz über den optionalen Bezeichner <code>role</code> qualifiziert werden kann.</li>\n</ul>"}, {"id": "FIG-26c9c84f9731ba52", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Mappings von Modellelementen und Instanzreferenzen über verschiedene Sichten hinweg im Rahmen der AUTOSAR Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ViewMapSet</strong> (<code>&lt;&lt;ARElement&gt;&gt;</code>): Eigenständiges Modellpaket bzw. Wurzelelement zur Bündelung von Abbildungsvorschriften; besitzt per Komposition (<code>+viewMap</code>, Multiplizität <code>0..*</code>) untergeordnete Abbildungen.</li>\n<li><strong>ViewMap</strong> (<code>&lt;&lt;Identifiable&gt;&gt;</code>): Repräsentiert ein einzelnes Mapping zwischen Modellelementen bzw. Instanzen. Besitzt das optionale Attribut <code>+ role :Identifier [0..1]</code>. Es verbindet Ziel- und Quellelemente über vier gerichtete Assoziationen:</li>\n<li><code>+firstElement</code>: Unidirektionale Assoziation auf <code>Referrable</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+secondElement</code>: Unidirektionale Assoziation auf <code>Referrable</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+firstElementInstance</code>: Komposition auf <code>AnyInstanceRef</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+secondElementInstance</code>: Komposition auf <code>AnyInstanceRef</code> (Multiplizität <code>0..*</code>).</li>\n<li><strong>Referrable</strong>: Abstraktes Ziel- bzw. Basiselement für referenzierbare Entitäten mit dem Attribut <code>+ shortName :Identifier</code>.</li>\n<li><strong>AnyInstanceRef</strong> (<code>&lt;&lt;AtpInstanceRef&gt;&gt;</code>): Repräsentiert konkrete Instanzreferenzen im Modellkontext, eingebettet in <code>ViewMap</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entitäten definieren deklarative Zuordnungen (Mapping-Definitionen) zwischen Paaren von Elementen (<code>firstElement</code> zu <code>secondElement</code>) bzw. konkreten Instanzreferenzen (<code>firstElementInstance</code> zu <code>secondElementInstance</code>), aggregiert in einem <code>ViewMapSet</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>ViewMapSet</code> dient als transportables <code>ARElement</code> im ARXML-Dateiaustausch.</li>\n<li>Eine <code>ViewMap</code> kann sowohl reine Definitionselemente (<code>Referrable</code>) als auch kontextspezifische Instanzen (<code>AnyInstanceRef</code>) aufeinander abbilden.</li>\n<li>Die Multiplizitäten <code>0..*</code> an allen vier Referenzrollen erlauben n:m-Beziehungen sowie einseitige oder leere Zuordnungen, wobei die semantische Konsistenz über den optionalen Bezeichner <code>role</code> qualifiziert werden kann.</li>\n</ul>"}, {"id": "FIG-06a16923c58e22b6", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Mappings von Modellelementen und Instanzreferenzen über verschiedene Sichten hinweg im Rahmen der AUTOSAR Generic Structure Template (<code>AUTOSAR_TPS_GenericStructureTemplate</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ViewMapSet</strong> (<code>&lt;&lt;ARElement&gt;&gt;</code>): Eigenständiges Modellpaket bzw. Wurzelelement zur Bündelung von Abbildungsvorschriften; besitzt per Komposition (<code>+viewMap</code>, Multiplizität <code>0..*</code>) untergeordnete Abbildungen.</li>\n<li><strong>ViewMap</strong> (<code>&lt;&lt;Identifiable&gt;&gt;</code>): Repräsentiert ein einzelnes Mapping zwischen Modellelementen bzw. Instanzen. Besitzt das optionale Attribut <code>+ role: Identifier [0..1]</code>. Es verbindet Ziel- und Quellelemente über vier Assoziationen:</li>\n<li><code>+firstElement</code>: Unidirektionale Assoziation auf <code>Referrable</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+secondElement</code>: Unidirektionale Assoziation auf <code>Referrable</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+firstElementInstance</code>: Komposition auf <code>AnyInstanceRef</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>+secondElementInstance</code>: Komposition auf <code>AnyInstanceRef</code> (Multiplizität <code>0..*</code>).</li>\n<li><strong>Referrable</strong>: Abstraktes Ziel- bzw. Basiselement für referenzierbare Entitäten mit dem Attribut <code>+ shortName: Identifier</code>.</li>\n<li><strong>AnyInstanceRef</strong> (<code>&lt;&lt;AtpInstanceRef&gt;&gt;</code>): Repräsentiert konkrete Instanzreferenzen im Modellkontext, eingebettet in <code>ViewMap</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entitäten definieren deklarative Zuordnungen (Mapping-Definitionen) zwischen Paaren von Elementen (<code>firstElement</code> zu <code>secondElement</code>) bzw. konkreten Instanzreferenzen (<code>firstElementInstance</code> zu <code>secondElementInstance</code>), aggregiert in einem <code>ViewMapSet</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>ViewMapSet</code> dient als transportables <code>ARElement</code> im ARXML-Dateiaustausch.</li>\n<li>Eine <code>ViewMap</code> kann sowohl reine Definitionselemente (<code>Referrable</code>) als auch kontextspezifische Instanzen (<code>AnyInstanceRef</code>) aufeinander abbilden.</li>\n<li>Die Multiplizitäten <code>0..*</code> an allen vier Referenzrollen erlauben n:m-Beziehungen sowie einseitige oder leere Zuordnungen, wobei die semantische Konsistenz über den optionalen Bezeichner <code>role</code> qualifiziert werden kann.</li>\n</ul>"}], "trans": [{"from": "FIG-aaa7e3f175f42b61", "to": "FIG-26c9c84f9731ba52", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-26c9c84f9731ba52", "to": "FIG-06a16923c58e22b6", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Referrable</code>: Abstand vor dem Doppelpunkt im Attribut <code>+ shortName: Identifier</code> entfernt (zuvor <code>+ shortName :Identifier</code>).</li>\n<li><code>ViewMap</code>: Abstand vor dem Doppelpunkt im Attribut <code>+ role: Identifier [0..1]</code> entfernt (zuvor <code>+ role :Identifier [0..1]</code>).</li>\n</ul>"}]};
